// AscendC KV RMSNorm + RoPE + Cache kernel — Norm cache mode
// Supports float16, bfloat16
// BNSD layout for kv, cos, sin, k_cache, ckv_cache

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_RMS = 256;
constexpr int32_t ROPE_SIZE_ALIGN = 64;  // rope_size is always 64 in practice

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutputHelper(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// KV RMSNorm + RoPE + Cache Kernel for Norm cache mode
// =========================================================================

template <typename dataType>
class KvRmsnormRopeCacheNormKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin,
        GM_ADDR index, GM_ADDR k_cache, GM_ADDR ckv_cache,
        GM_ADDR k_cache_out_gm, GM_ADDR ckv_cache_out_gm,
        GM_ADDR k_embed_out_gm, GM_ADDR v_out_gm,
        int32_t B, int32_t N, int32_t S, int32_t D,
        int32_t rms_size, int32_t rope_size,
        int32_t k_cache_seq, int32_t ckv_cache_seq,
        int32_t usedCoreNum, int32_t tasksPerCore,
        float epsilon)
    {
        this->B_ = B;
        this->N_ = N;
        this->S_ = S;
        this->D_ = D;
        this->rmsSize_ = rms_size;
        this->ropeSize_ = rope_size;
        this->kCacheSeq_ = k_cache_seq;
        this->ckvCacheSeq_ = ckv_cache_seq;
        this->usedCoreNum_ = usedCoreNum;
        this->tasksPerCore_ = tasksPerCore;
        this->eps_ = epsilon;

        uint64_t kvByteSize = static_cast<uint64_t>(B) * N * S * D;
        uint64_t cosByteSize = static_cast<uint64_t>(B) * N * S * rope_size;
        kvGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(kv), kvByteSize);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), rms_size);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos), cosByteSize);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin), cosByteSize);
        indexGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(index), static_cast<uint64_t>(B) * S);

        uint64_t kCacheByteSize = static_cast<uint64_t>(B) * N * k_cache_seq * rope_size;
        uint64_t ckvCacheByteSize = static_cast<uint64_t>(B) * N * ckv_cache_seq * rms_size;
        kCacheGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(k_cache), kCacheByteSize);
        ckvCacheGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(ckv_cache), ckvCacheByteSize);

        kCacheOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(k_cache_out_gm), kCacheByteSize);
        ckvCacheOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(ckv_cache_out_gm), ckvCacheByteSize);

        uint64_t kEmbedOutByteSize = static_cast<uint64_t>(B) * N * S * rope_size;
        uint64_t vOutByteSize = static_cast<uint64_t>(B) * N * S * rms_size;
        kEmbedOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(k_embed_out_gm), kEmbedOutByteSize);
        vOutGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(v_out_gm), vOutByteSize);

        if ASCEND_IS_AIV {
            InitAivBuffers();
        }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // RMS input queues
        pipe_.InitBuffer(rmsInQueue_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        pipe_.InitBuffer(rmsOutQueue_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        // RoPE input queues
        pipe_.InitBuffer(ropeInQueue_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        pipe_.InitBuffer(ropeOutQueue_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        // Cos/sin queue
        pipe_.InitBuffer(cosInQueue_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        pipe_.InitBuffer(sinInQueue_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        // Gamma queue
        pipe_.InitBuffer(gammaInQueue_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        // Cache output queues
        pipe_.InitBuffer(kCacheOutQueue_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        pipe_.InitBuffer(ckvCacheOutQueue_, BUFFER_NUM, TILE_RMS * sizeof(dataType));

        // Compute buffers
        pipe_.InitBuffer(rmsReduceBuf_, TILE_RMS * sizeof(float));
        pipe_.InitBuffer(rmsSumBuf_, 16 * sizeof(float));
        pipe_.InitBuffer(rmsInvScaleBuf_, sizeof(float));
        pipe_.InitBuffer(ropeComputeBuf_, ROPE_SIZE_ALIGN * sizeof(float));
        pipe_.InitBuffer(ropeHalfBuf_, (ROPE_SIZE_ALIGN / 2) * sizeof(float));
        pipe_.InitBuffer(ropeCosFp32Buf_, ROPE_SIZE_ALIGN * sizeof(float));
        pipe_.InitBuffer(ropeSinFp32Buf_, ROPE_SIZE_ALIGN * sizeof(float));

        // Cast buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(rmsCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(gammaCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(rmsOutCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(ropeCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(ropeOutCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(cosCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(sinCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(kCacheCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(ckvCacheCastBuf_, TILE_RMS * sizeof(float));
        }

        // Index queue (int64)
        pipe_.InitBuffer(indexQueue_, BUFFER_NUM, 2 * sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx();
            int32_t totalHeads = B_ * N_;

            for (int32_t localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                int32_t headGroup = coreIdx * tasksPerCore_ + localIdx;
                if (headGroup >= totalHeads) {
                    continue;
                }

                int32_t b = headGroup / N_;
                int32_t n = headGroup % N_;

                for (int32_t s = 0; s < S_; ++s) {
                    ProcessPosition(b, n, s);
                }
            }
        }
    }

private:
    // -----------------------------------------------------------------------
    // Per-position processing
    // -----------------------------------------------------------------------
    __aicore__ inline void ProcessPosition(int32_t b, int32_t n, int32_t s)
    {
        // ---- RMSNorm ----
        float invRms = ComputeInvRms(b, n, s);
        ComputeRmsNormAndWriteOut(b, n, s, invRms);

        // ---- RoPE ----
        ComputeRopeAndWriteOut(b, n, s);

        // ---- Cache scatter ----
        CacheScatter(b, n, s);
    }

    // -----------------------------------------------------------------------
    // RMSNorm: Pass 1 — accumulate sum(x^2) over rms_size tiles
    // -----------------------------------------------------------------------
    __aicore__ inline float ComputeInvRms(int32_t b, int32_t n, int32_t s)
    {
        float sumSq = 0.0f;
        int32_t nTiles = CeilDivU32(static_cast<uint32_t>(rmsSize_), TILE_RMS);

        for (int32_t t = 0; t < nTiles; ++t) {
            int32_t colStart = t * TILE_RMS;
            int32_t curLen = (colStart + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - colStart);

            // Load rms_in tile from kv[b,n,s,colStart:]
            rmsInLocal_ = rmsInQueue_.AllocTensor<dataType>();
            uint64_t rmsOffset = static_cast<uint64_t>(b) * N_ * S_ * D_
                                 + static_cast<uint64_t>(n) * S_ * D_
                                 + static_cast<uint64_t>(s) * D_
                                 + colStart;
            LoadGmToUb(rmsInLocal_, kvGM_[rmsOffset], static_cast<uint32_t>(curLen));
            rmsInQueue_.EnQue(rmsInLocal_);

            // Compute sum of squares
            rmsInLocal_ = rmsInQueue_.DeQue<dataType>();
            PrepareInputHelper<dataType>(rmsFp32Local_, rmsInLocal_, rmsCastBuf_, curLen);

            // Square and reduce
            AscendC::LocalTensor<float> sqLocal = rmsReduceBuf_.Get<float>();
            rmsReduceLocal_ = rmsReduceBuf_.Get<float>();
            rmsSumLocal_ = rmsSumBuf_.Get<float>();

            AscendC::Mul(sqLocal, rmsFp32Local_, rmsFp32Local_, curLen);
            AscendC::ReduceSum<float>(rmsSumLocal_, sqLocal, rmsReduceLocal_, curLen);
            sumSq += rmsSumLocal_.GetValue(0);

            rmsInQueue_.FreeTensor(rmsInLocal_);
        }

        // Compute inv_rms = 1/sqrt(mean(x^2) + eps)
        float invN = 1.0f / static_cast<float>(rmsSize_);
        float invRmsVal = rsqrtf(sumSq * invN + eps_);
        return invRmsVal;
    }

    // -----------------------------------------------------------------------
    // RMSNorm: Pass 2 — normalize + gamma → v_out
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeRmsNormAndWriteOut(int32_t b, int32_t n, int32_t s, float invRms)
    {
        int32_t nTiles = CeilDivU32(static_cast<uint32_t>(rmsSize_), TILE_RMS);

        for (int32_t t = 0; t < nTiles; ++t) {
            int32_t colStart = t * TILE_RMS;
            int32_t curLen = (colStart + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - colStart);

            // Load rms_in
            rmsInLocal_ = rmsInQueue_.AllocTensor<dataType>();
            uint64_t rmsOffset = static_cast<uint64_t>(b) * N_ * S_ * D_
                                 + static_cast<uint64_t>(n) * S_ * D_
                                 + static_cast<uint64_t>(s) * D_
                                 + colStart;
            LoadGmToUb(rmsInLocal_, kvGM_[rmsOffset], static_cast<uint32_t>(curLen));
            rmsInQueue_.EnQue(rmsInLocal_);

            // Load gamma
            gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
            LoadGmToUb(gammaInLocal_, gammaGM_[colStart], static_cast<uint32_t>(curLen));
            gammaInQueue_.EnQue(gammaInLocal_);

            // Allocate output
            rmsOutLocal_ = rmsOutQueue_.AllocTensor<dataType>();

            // Compute
            rmsInLocal_ = rmsInQueue_.DeQue<dataType>();
            gammaInLocal_ = gammaInQueue_.DeQue<dataType>();

            PrepareInputHelper<dataType>(rmsFp32Local_, rmsInLocal_, rmsCastBuf_, curLen);
            PrepareInputHelper<dataType>(gammaFp32Local_, gammaInLocal_, gammaCastBuf_, curLen);

            // Prepare output
            if constexpr (std::is_same_v<dataType, float>) {
                rmsOutFp32Local_ = rmsOutLocal_.template ReinterpretCast<float>();
            } else {
                rmsOutFp32Local_ = rmsOutCastBuf_.Get<float>();
            }

            // v = gamma * rms_in * inv_rms
            AscendC::Muls(rmsOutFp32Local_, rmsFp32Local_, invRms, curLen);
            AscendC::Mul(rmsOutFp32Local_, rmsOutFp32Local_, gammaFp32Local_, curLen);
            FinalizeOutputHelper<dataType>(rmsOutLocal_, rmsOutFp32Local_, curLen);

            rmsInQueue_.FreeTensor(rmsInLocal_);
            gammaInQueue_.FreeTensor(gammaInLocal_);

            rmsOutQueue_.EnQue(rmsOutLocal_);

            // Write v_out
            rmsOutLocal_ = rmsOutQueue_.DeQue<dataType>();
            uint64_t vOutOffset = static_cast<uint64_t>(b) * N_ * S_ * rmsSize_
                                  + static_cast<uint64_t>(n) * S_ * rmsSize_
                                  + static_cast<uint64_t>(s) * rmsSize_
                                  + colStart;
            StoreUbToGm(vOutGM_[vOutOffset], rmsOutLocal_, static_cast<uint32_t>(curLen));
            rmsOutQueue_.FreeTensor(rmsOutLocal_);
        }
    }

    // -----------------------------------------------------------------------
    // RoPE computation on rope_size elements
    // -----------------------------------------------------------------------
    __aicore__ inline void ComputeRopeAndWriteOut(int32_t b, int32_t n, int32_t s)
    {
        if (ropeSize_ == 0) { return; }

        // Load rope_in from kv
        ropeInLocal_ = ropeInQueue_.AllocTensor<dataType>();
        uint64_t ropeOffset = static_cast<uint64_t>(b) * N_ * S_ * D_
                              + static_cast<uint64_t>(n) * S_ * D_
                              + static_cast<uint64_t>(s) * D_
                              + rmsSize_;
        LoadGmToUb(ropeInLocal_, kvGM_[ropeOffset], static_cast<uint32_t>(ropeSize_));
        ropeInQueue_.EnQue(ropeInLocal_);

        // Load cos for this position
        cosInLocal_ = cosInQueue_.AllocTensor<dataType>();
        uint64_t cosOffset = static_cast<uint64_t>(b) * N_ * S_ * ropeSize_
                             + static_cast<uint64_t>(n) * S_ * ropeSize_
                             + static_cast<uint64_t>(s) * ropeSize_;
        LoadGmToUb(cosInLocal_, cosGM_[cosOffset], static_cast<uint32_t>(ropeSize_));
        cosInQueue_.EnQue(cosInLocal_);

        // Load sin for this position
        sinInLocal_ = sinInQueue_.AllocTensor<dataType>();
        LoadGmToUb(sinInLocal_, sinGM_[cosOffset], static_cast<uint32_t>(ropeSize_));
        sinInQueue_.EnQue(sinInLocal_);

        // Allocate k_embed output
        ropeOutLocal_ = ropeOutQueue_.AllocTensor<dataType>();

        // DeQue all inputs
        ropeInLocal_ = ropeInQueue_.DeQue<dataType>();
        cosInLocal_ = cosInQueue_.DeQue<dataType>();
        sinInLocal_ = sinInQueue_.DeQue<dataType>();

        PrepareInputHelper<dataType>(ropeFp32Local_, ropeInLocal_, ropeCastBuf_, ropeSize_);
        PrepareInputHelper<dataType>(cosFp32Local_, cosInLocal_, cosCastBuf_, ropeSize_);
        PrepareInputHelper<dataType>(sinFp32Local_, sinInLocal_, sinCastBuf_, ropeSize_);

        // Prepare k_embed output
        if constexpr (std::is_same_v<dataType, float>) {
            ropeOutFp32Local_ = ropeOutLocal_.template ReinterpretCast<float>();
        } else {
            ropeOutFp32Local_ = ropeOutCastBuf_.Get<float>();
        }

        // ---- RoPE computation ----
        // rope_in = [a0, a1, a2, a3, ..., a_{d-2}, a_{d-1}]
        // Step 1: Interleave to k = [a0, a2, ..., a_{d-2}, a1, a3, ..., a_{d-1}]
        int32_t half = ropeSize_ / 2;

        // Gather even and odd elements using interleaved pattern
        AscendC::LocalTensor<float> kInterleaved = ropeComputeBuf_.Get<float>();
        AscendC::LocalTensor<float> kEven = ropeHalfBuf_.Get<float>();
        AscendC::LocalTensor<float> kOdd = ropeHalfBuf_.Get<float>();

        // We need to manually interleave: k=even half first, then odd half
        // Since GatherMask with P0101/P1010 yields half the elements

        // Build interleaved k: even indices first, then odd indices
        // In AscendC we do this by accessing every other element
        // k[i] = rope_in[2*i] for i in [0, half), k[half+i] = rope_in[2*i+1]
        // We'll use a scatter approach or explicit element-by-element
        // Since AscendC doesn't have direct gather for this pattern,
        // we use a loop or a specialized approach

        // Approach: Use 2-element window with stride-2 access
        {
            AscendC::LocalTensor<float> rmsSqTmp = rmsReduceBuf_.Get<float>();
            // Use a simple interleave: copy even elements then odd elements
            int32_t i = 0;
            // Even elements: rope_in[0], rope_in[2], ..., rope_in[ropeSize_-2]
            for (i = 0; i < half; ++i) {
                kEven.SetValue(i, ropeFp32Local_.GetValue(2 * i));
            }
            // Odd elements: rope_in[1], rope_in[3], ..., rope_in[ropeSize_-1]
            for (i = 0; i < half; ++i) {
                kOdd.SetValue(i, ropeFp32Local_.GetValue(2 * i + 1));
            }
            // Build interleaved: k = even | odd
            for (i = 0; i < half; ++i) {
                kInterleaved.SetValue(i, kEven.GetValue(i));
            }
            for (i = 0; i < half; ++i) {
                kInterleaved.SetValue(half + i, kOdd.GetValue(i));
            }

            // Step 2: Compute rotate_half_k = [-odd | even]
            AscendC::LocalTensor<float> rotateHalf = rmsOutFp32Local_;  // reuse rmsOutFp32 buffer
            for (i = 0; i < half; ++i) {
                rotateHalf.SetValue(i, -kOdd.GetValue(i));
            }
            for (i = 0; i < half; ++i) {
                rotateHalf.SetValue(half + i, kEven.GetValue(i));
            }

            // Step 3: k_embed = k * cos + rotate_half_k * sin
            AscendC::Mul(kInterleaved, kInterleaved, cosFp32Local_, ropeSize_);
            AscendC::Mul(rotateHalf, rotateHalf, sinFp32Local_, ropeSize_);
            AscendC::Add(ropeOutFp32Local_, kInterleaved, rotateHalf, ropeSize_);
        }

        FinalizeOutputHelper<dataType>(ropeOutLocal_, ropeOutFp32Local_, ropeSize_);

        ropeInQueue_.FreeTensor(ropeInLocal_);
        cosInQueue_.FreeTensor(cosInLocal_);
        sinInQueue_.FreeTensor(sinInLocal_);

        ropeOutQueue_.EnQue(ropeOutLocal_);

        // Write k_embed_out
        ropeOutLocal_ = ropeOutQueue_.DeQue<dataType>();
        uint64_t kEmbedOutOffset = static_cast<uint64_t>(b) * N_ * S_ * ropeSize_
                                   + static_cast<uint64_t>(n) * S_ * ropeSize_
                                   + static_cast<uint64_t>(s) * ropeSize_;
        StoreUbToGm(kEmbedOutGM_[kEmbedOutOffset], ropeOutLocal_, static_cast<uint32_t>(ropeSize_));
        ropeOutQueue_.FreeTensor(ropeOutLocal_);
    }

    // -----------------------------------------------------------------------
    // Cache scatter for Norm mode
    // -----------------------------------------------------------------------
    __aicore__ inline void CacheScatter(int32_t b, int32_t n, int32_t s)
    {
        // Load index for this (b,s) position
        // index is [B, S] in BNSD layout
        auto &idxLocal = indexQueue_.AllocTensor<int64_t>();
        uint64_t idxOffset = static_cast<uint64_t>(b) * S_ + s;
        AscendC::DataCopyExtParams copyParams{1, sizeof(int64_t), 0, 0, 0};
        AscendC::DataCopyPadExtParams<int64_t> padParams{true, 0, 0, static_cast<int64_t>(0)};
        AscendC::DataCopyPad(idxLocal, indexGM_[idxOffset], copyParams, padParams);
        indexQueue_.EnQue(idxLocal);

        idxLocal = indexQueue_.DeQue<int64_t>();
        int64_t idx = idxLocal.GetValue(0);
        indexQueue_.FreeTensor(idxLocal);

        if (idx < 0 || idx >= kCacheSeq_) {
            return;
        }

        // Write k_for_cache (k_embed) to k_cache_out[b, n, idx, :]
        // Load k_embed_out data
        {
            ropeInLocal_ = ropeInQueue_.AllocTensor<dataType>();
            uint64_t kEmbedOffset = static_cast<uint64_t>(b) * N_ * S_ * ropeSize_
                                    + static_cast<uint64_t>(n) * S_ * ropeSize_
                                    + static_cast<uint64_t>(s) * ropeSize_;
            LoadGmToUb(ropeInLocal_, kEmbedOutGM_[kEmbedOffset], static_cast<uint32_t>(ropeSize_));
            ropeInQueue_.EnQue(ropeInLocal_);

            kCacheOutLocal_ = kCacheOutQueue_.AllocTensor<dataType>();
            ropeInLocal_ = ropeInQueue_.DeQue<dataType>();

            // Copy rope data to k_cache_out buffer (same data, just to different location)
            AscendC::Duplicate(kCacheOutLocal_, static_cast<dataType>(0), ropeSize_);
            // Actually, we just copy the rope data directly
            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::DataCopy(kCacheOutLocal_, ropeInLocal_, ropeSize_);
            } else {
                kCacheFp32Local_ = kCacheCastBuf_.Get<float>();
                PrepareInputHelper<dataType>(kCacheFp32Local_, ropeInLocal_, ropeCastBuf_, ropeSize_);
                PrepareInputHelper<dataType>(ropeOutFp32Local_, kCacheOutLocal_, ropeOutCastBuf_, ropeSize_);
                AscendC::DataCopy(ropeOutFp32Local_, kCacheFp32Local_, ropeSize_);
                FinalizeOutputHelper<dataType>(kCacheOutLocal_, ropeOutFp32Local_, ropeSize_);
            }

            ropeInQueue_.FreeTensor(ropeInLocal_);
            kCacheOutQueue_.EnQue(kCacheOutLocal_);

            kCacheOutLocal_ = kCacheOutQueue_.DeQue<dataType>();
            uint64_t kCacheOutOffset = static_cast<uint64_t>(b) * N_ * kCacheSeq_ * ropeSize_
                                       + static_cast<uint64_t>(n) * kCacheSeq_ * ropeSize_
                                       + static_cast<uint64_t>(idx) * ropeSize_;
            StoreUbToGm(kCacheOutGM_[kCacheOutOffset], kCacheOutLocal_, static_cast<uint32_t>(ropeSize_));
            kCacheOutQueue_.FreeTensor(kCacheOutLocal_);
        }

        // Write v_for_cache to ckv_cache_out[b, n, idx, :]
        {
            rmsInLocal_ = rmsInQueue_.AllocTensor<dataType>();
            uint64_t vOutOffset = static_cast<uint64_t>(b) * N_ * S_ * rmsSize_
                                  + static_cast<uint64_t>(n) * S_ * rmsSize_
                                  + static_cast<uint64_t>(s) * rmsSize_;
            LoadGmToUb(rmsInLocal_, vOutGM_[vOutOffset], static_cast<uint32_t>(rmsSize_));
            rmsInQueue_.EnQue(rmsInLocal_);

            // We need to handle rms_size (512) which exceeds single tile
            // So tile it
            int32_t cacheTiles = CeilDivU32(static_cast<uint32_t>(rmsSize_), TILE_RMS);
            for (int32_t t = 0; t < cacheTiles; ++t) {
                int32_t colStart = t * TILE_RMS;
                int32_t curLen = (colStart + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - colStart);

                rmsInLocal_ = rmsInQueue_.DeQue<dataType>();
                // Extract the relevant portion (simplified: load fresh per tile)
                // Since rms_size may be larger than TILE_RMS, we re-load from v_out

                ckvCacheOutLocal_ = ckvCacheOutQueue_.AllocTensor<dataType>();

                // Copy data from loaded rms_in to ckv_cache_out destination
                if constexpr (std::is_same_v<dataType, float>) {
                    AscendC::DataCopy(ckvCacheOutLocal_, rmsInLocal_, curLen);
                } else {
                    ckvCacheFp32Local_ = ckvCacheCastBuf_.Get<float>();
                    PrepareInputHelper<dataType>(ckvCacheFp32Local_, rmsInLocal_, rmsCastBuf_, curLen);
                    PrepareInputHelper<dataType>(rmsOutFp32Local_, ckvCacheOutLocal_, rmsOutCastBuf_, curLen);
                    AscendC::DataCopy(rmsOutFp32Local_, ckvCacheFp32Local_, curLen);
                    FinalizeOutputHelper<dataType>(ckvCacheOutLocal_, rmsOutFp32Local_, curLen);
                }

                rmsInQueue_.FreeTensor(rmsInLocal_);
                ckvCacheOutQueue_.EnQue(ckvCacheOutLocal_);

                ckvCacheOutLocal_ = ckvCacheOutQueue_.DeQue<dataType>();
                uint64_t ckvCacheOutOffset = static_cast<uint64_t>(b) * N_ * ckvCacheSeq_ * rmsSize_
                                             + static_cast<uint64_t>(n) * ckvCacheSeq_ * rmsSize_
                                             + static_cast<uint64_t>(idx) * rmsSize_
                                             + colStart;
                StoreUbToGm(ckvCacheOutGM_[ckvCacheOutOffset], ckvCacheOutLocal_, static_cast<uint32_t>(curLen));
                ckvCacheOutQueue_.FreeTensor(ckvCacheOutLocal_);

                // Re-load next tile from v_out if needed
                if (t + 1 < cacheTiles) {
                    rmsInLocal_ = rmsInQueue_.AllocTensor<dataType>();
                    uint64_t reLoadOffset = vOutOffset + colStart + TILE_RMS;
                    int32_t nextLen = ((colStart + 2 * TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - colStart - TILE_RMS));
                    LoadGmToUb(rmsInLocal_, vOutGM_[reLoadOffset], static_cast<uint32_t>(nextLen));
                    rmsInQueue_.EnQue(rmsInLocal_);
                }
            }
        }
    }

