// Host-side: KV RMSNorm + RoPE + Cache operator
// Tiling + kernel launch via EXEC_KERNEL_CMD

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_kv_rmsnorm_rope_cache_norm.h"

namespace ascend_kernel {

at::Tensor kv_rmsnorm_rope_cache(
    const at::Tensor &kv,
    const at::Tensor &gamma,
    const at::Tensor &cos,
    const at::Tensor &sin,
    const at::Tensor &index,
    const at::Tensor &k_cache,
    const at::Tensor &ckv_cache)
{
    // Input validation
    TORCH_CHECK(kv.dim() == 4, "kv must be 4D [B,N,S,D]");
    TORCH_CHECK(kv.dtype() == at::kHalf || kv.dtype() == at::kBFloat16,
                "kv dtype must be float16 or bfloat16");
    TORCH_CHECK(kv.is_contiguous(), "kv must be contiguous");
    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
    TORCH_CHECK(cos.is_contiguous(), "cos must be contiguous");
    TORCH_CHECK(sin.is_contiguous(), "sin must be contiguous");
    TORCH_CHECK(index.dtype() == at::kLong, "index dtype must be int64");

    int64_t B = kv.size(0);
    int64_t N = kv.size(1);
    int64_t S = kv.size(2);
    int64_t D = kv.size(3);
    int64_t rmsSize = gamma.size(0);
    int64_t ropeSize = D - rmsSize;
    int64_t kCacheSeq = k_cache.size(2);
    int64_t ckvCacheSeq = ckv_cache.size(2);

    // Platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    int64_t totalHeads = B * N;
    int64_t numPhysicalCores = 20;
    int64_t usedCoreNum = (totalHeads < numPhysicalCores) ? totalHeads : numPhysicalCores;
    int64_t tasksPerCore = (totalHeads + usedCoreNum - 1) / usedCoreNum;

    float epsilonVal = 1e-5f;

    // Create output tensors
    auto k_embed_out = at::empty({B, N, S, ropeSize}, kv.options());
    auto v_out = at::empty({B, N, S, rmsSize}, kv.options());

    // Copy cache tensors (out-of-place)
    auto k_cache_out = k_cache.clone();
    auto ckv_cache_out = ckv_cache.clone();

    // dtype flag
    int64_t dtypeFlag = (kv.dtype() == at::kHalf) ? 1 : 2;

    // Launch kernel — all params must be lvalues
    int32_t B_i32 = static_cast<int32_t>(B);
    int32_t N_i32 = static_cast<int32_t>(N);
    int32_t S_i32 = static_cast<int32_t>(S);
    int32_t D_i32 = static_cast<int32_t>(D);
    int32_t rmsSize_i32 = static_cast<int32_t>(rmsSize);
    int32_t ropeSize_i32 = static_cast<int32_t>(ropeSize);
    int32_t kCacheSeq_i32 = static_cast<int32_t>(kCacheSeq);
    int32_t ckvCacheSeq_i32 = static_cast<int32_t>(ckvCacheSeq);
    int32_t usedCoreNum_i32 = static_cast<int32_t>(usedCoreNum);
    int32_t tasksPerCore_i32 = static_cast<int32_t>(tasksPerCore);
    float epsFloat = epsilonVal;

    EXEC_KERNEL_CMD(
        kv_rmsnorm_rope_cache_norm, usedCoreNum_i32,
        kv, gamma, cos, sin, index, k_cache, ckv_cache,
        k_cache_out, ckv_cache_out, k_embed_out, v_out,
        B_i32, N_i32, S_i32, D_i32,
        rmsSize_i32, ropeSize_i32,
        kCacheSeq_i32, ckvCacheSeq_i32,
        usedCoreNum_i32, tasksPerCore_i32,
        epsFloat,
        dtypeFlag);

    return torch::cat({k_cache_out, ckv_cache_out, k_embed_out, v_out}, 0);
}

} // namespace ascend_kernel
