// AscendC KV RMSNorm + RoPE + Cache kernel — Norm cache mode
// BNSD layout for all tensors. dtype dispatch: fp16/bf16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_RMS = 256;
constexpr int32_t ROPE_SIZE_ALIGN = 64;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / bU;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * (uint32_t)sizeof(T), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * (uint32_t)sizeof(T), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputHelper(
    AscendC::LocalTensor<float> &dst, AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf, int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutputHelper(
    AscendC::LocalTensor<T> &out, AscendC::LocalTensor<float> &src, int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// KV RMSNorm + RoPE + Cache Kernel (Norm mode)
// =========================================================================

template <typename dataType>
class KvRmsnormRopeCacheNormKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin,
        GM_ADDR index, GM_ADDR k_cache, GM_ADDR ckv_cache,
        GM_ADDR kc_out, GM_ADDR ckv_out, GM_ADDR ke_out, GM_ADDR v_out,
        int32_t B, int32_t N, int32_t S, int32_t D,
        int32_t rmsSize, int32_t ropeSize,
        int32_t kCacheSeq, int32_t ckvCacheSeq,
        int32_t usedCoreNum, int32_t tasksPerCore, float epsilon)
    {
        B_ = B; N_ = N; S_ = S; D_ = D;
        rmsSize_ = rmsSize; ropeSize_ = ropeSize;
        kCacheSeq_ = kCacheSeq; ckvCacheSeq_ = ckvCacheSeq;
        usedCoreNum_ = usedCoreNum; tasksPerCore_ = tasksPerCore;
        eps_ = epsilon;

        uint64_t kvSz   = (uint64_t)B * N * S * D;
        uint64_t cosSz  = (uint64_t)B * N * S * ropeSize;
        uint64_t idxSz  = (uint64_t)B * S;
        uint64_t kcSz   = (uint64_t)B * N * kCacheSeq * ropeSize;
        uint64_t ccSz   = (uint64_t)B * N * ckvCacheSeq * rmsSize;
        uint64_t keSz   = (uint64_t)B * N * S * ropeSize;
        uint64_t voSz   = (uint64_t)B * N * S * rmsSize;

        kvGM_.SetGlobalBuffer((__gm__ dataType*)kv, kvSz);
        gammaGM_.SetGlobalBuffer((__gm__ dataType*)gamma, rmsSize);
        cosGM_.SetGlobalBuffer((__gm__ dataType*)cos, cosSz);
        sinGM_.SetGlobalBuffer((__gm__ dataType*)sin, cosSz);
        indexGM_.SetGlobalBuffer((__gm__ int64_t*)index, idxSz);
        kCacheGM_.SetGlobalBuffer((__gm__ dataType*)k_cache, kcSz);
        ckvCacheGM_.SetGlobalBuffer((__gm__ dataType*)ckv_cache, ccSz);
        kCacheOutGM_.SetGlobalBuffer((__gm__ dataType*)kc_out, kcSz);
        ckvCacheOutGM_.SetGlobalBuffer((__gm__ dataType*)ckv_out, ccSz);
        kEmbedOutGM_.SetGlobalBuffer((__gm__ dataType*)ke_out, keSz);
        vOutGM_.SetGlobalBuffer((__gm__ dataType*)v_out, voSz);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        // RMS queues
        pipe_.InitBuffer(rmsInQ_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        pipe_.InitBuffer(rmsGammaQ_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        pipe_.InitBuffer(rmsOutQ_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        // RoPE queues
        pipe_.InitBuffer(ropeInQ_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        pipe_.InitBuffer(ropeCosQ_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        pipe_.InitBuffer(ropeSinQ_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        pipe_.InitBuffer(ropeOutQ_, BUFFER_NUM, ROPE_SIZE_ALIGN * sizeof(dataType));
        // Cache queues
        pipe_.InitBuffer(cacheInQ_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        pipe_.InitBuffer(cacheOutQ_, BUFFER_NUM, TILE_RMS * sizeof(dataType));
        // Compute buffers
        pipe_.InitBuffer(rmsReduceBuf_, TILE_RMS * sizeof(float));
        pipe_.InitBuffer(rmsSumBuf_, 16 * sizeof(float));
        pipe_.InitBuffer(rmsInvBuf_, sizeof(float));
        pipe_.InitBuffer(ropeFp32Buf_, ROPE_SIZE_ALIGN * sizeof(float));
        // Cast buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe_.InitBuffer(rmsCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(rmsGammaCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(rmsOutCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(ropeCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(ropeCosCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(ropeSinCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(ropeOutCastBuf_, ROPE_SIZE_ALIGN * sizeof(float));
            pipe_.InitBuffer(cacheCastBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(cacheOutCastBuf_, TILE_RMS * sizeof(float));
        }
        // Index buffer (4 int64 = 32 bytes for alignment)
        pipe_.InitBuffer(idxBuf_, 4 * sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int32_t totalHeads = B_ * N_;
            for (int32_t li = 0; li < tasksPerCore_; ++li) {
                int32_t hg = coreIdx * tasksPerCore_ + li;
                if (hg >= totalHeads) continue;
                int32_t b = hg / N_;
                int32_t n = hg % N_;
                for (int32_t s = 0; s < S_; ++s) {
                    ProcessPosition(b, n, s);
                }
            }
        }
    }

private:
    // =======================================================================
    // Per-position processing
    // =======================================================================
    __aicore__ inline void ProcessPosition(int32_t b, int32_t n, int32_t s)
    {
        float invRms = ComputeInvRms(b, n, s);
        ComputeRmsNormAndWriteOut(b, n, s, invRms);
        ComputeRopeAndWriteOut(b, n, s);
        CacheScatter(b, n, s);
    }

    // =======================================================================
    // RMSNorm: accumulate sum(x^2) → inv_rms
    // =======================================================================
    __aicore__ inline float ComputeInvRms(int32_t b, int32_t n, int32_t s)
    {
        float sumSq = 0.0f;
        int32_t nTiles = CeilDivU32((uint32_t)rmsSize_, TILE_RMS);
        for (int32_t t = 0; t < nTiles; ++t) {
            int32_t cs = t * TILE_RMS;
            int32_t len = (cs + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - cs);
            uint64_t off = (uint64_t)b * N_ * S_ * D_ + (uint64_t)n * S_ * D_ + (uint64_t)s * D_ + cs;

            AscendC::LocalTensor<dataType> rmsIn = rmsInQ_.AllocTensor<dataType>();
            LoadGmToUb(rmsIn, kvGM_[off], (uint32_t)len);
            rmsInQ_.EnQue(rmsIn);
            rmsIn = rmsInQ_.DeQue<dataType>();

            AscendC::LocalTensor<float> fp32Tmp;
            PrepareInputHelper<dataType>(fp32Tmp, rmsIn, rmsCastBuf_, len);
            AscendC::LocalTensor<float> sqTmp = rmsReduceBuf_.Get<float>();
            AscendC::LocalTensor<float> sumTmp = rmsSumBuf_.Get<float>();
            AscendC::Mul(sqTmp, fp32Tmp, fp32Tmp, len);
            AscendC::ReduceSum<float>(sumTmp, sqTmp, sqTmp, len);
            sumSq += sumTmp.GetValue(0);
            rmsInQ_.FreeTensor(rmsIn);
        }
        float meanSq = sumSq / (float)rmsSize_ + eps_;
        AscendC::LocalTensor<float> st = rmsSumBuf_.Get<float>();
        AscendC::LocalTensor<float> iv = rmsInvBuf_.Get<float>();
        AscendC::Duplicate(st, meanSq, 1);
        AscendC::Rsqrt(iv, st, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float result = iv.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();
        return result;
    }

    // =======================================================================
    // RMSNorm: normalize + gamma → v_out
    // =======================================================================
    __aicore__ inline void ComputeRmsNormAndWriteOut(int32_t b, int32_t n, int32_t s, float invRms)
    {
        int32_t nTiles = CeilDivU32((uint32_t)rmsSize_, TILE_RMS);
        for (int32_t t = 0; t < nTiles; ++t) {
            int32_t cs = t * TILE_RMS;
            int32_t len = (cs + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - cs);
            uint64_t off = (uint64_t)b * N_ * S_ * D_ + (uint64_t)n * S_ * D_ + (uint64_t)s * D_ + cs;
            uint64_t vOff = (uint64_t)b * N_ * S_ * rmsSize_ + (uint64_t)n * S_ * rmsSize_ + (uint64_t)s * rmsSize_ + cs;

            AscendC::LocalTensor<dataType> rmsIn = rmsInQ_.AllocTensor<dataType>();
            LoadGmToUb(rmsIn, kvGM_[off], (uint32_t)len);
            rmsInQ_.EnQue(rmsIn);
            AscendC::LocalTensor<dataType> gamIn = rmsGammaQ_.AllocTensor<dataType>();
            LoadGmToUb(gamIn, gammaGM_[cs], (uint32_t)len);
            rmsGammaQ_.EnQue(gamIn);
            AscendC::LocalTensor<dataType> rmsOut = rmsOutQ_.AllocTensor<dataType>();
            rmsIn = rmsInQ_.DeQue<dataType>();
            gamIn = rmsGammaQ_.DeQue<dataType>();

            AscendC::LocalTensor<float> xFp32, gFp32, yFp32;
            PrepareInputHelper<dataType>(xFp32, rmsIn, rmsCastBuf_, len);
            PrepareInputHelper<dataType>(gFp32, gamIn, rmsGammaCastBuf_, len);
            if constexpr (std::is_same_v<dataType, float>) {
                yFp32 = rmsOut.template ReinterpretCast<float>();
            } else {
                yFp32 = rmsOutCastBuf_.Get<float>();
            }
            AscendC::Muls(yFp32, xFp32, invRms, len);
            AscendC::Mul(yFp32, yFp32, gFp32, len);
            FinalizeOutputHelper<dataType>(rmsOut, yFp32, len);
            rmsInQ_.FreeTensor(rmsIn);
            rmsGammaQ_.FreeTensor(gamIn);
            rmsOutQ_.EnQue(rmsOut);

            rmsOut = rmsOutQ_.DeQue<dataType>();
            StoreUbToGm(vOutGM_[vOff], rmsOut, (uint32_t)len);
            rmsOutQ_.FreeTensor(rmsOut);
        }
    }

    // =======================================================================
    // RoPE: interleave + rotate (vectorized, no scalar loops)
    // Strategy: compute in standard order {a0',a1',a2',a3',...,a63'},
    // then interleave to {a0',a2',...,a62', a1',a3',...,a63'}.
    // =======================================================================
    __aicore__ inline void ComputeRopeAndWriteOut(int32_t b, int32_t n, int32_t s)
    {
        if (ropeSize_ == 0) return;
        int32_t half = ropeSize_ / 2;
        uint64_t rOff = (uint64_t)b * N_ * S_ * D_ + (uint64_t)n * S_ * D_ + (uint64_t)s * D_ + rmsSize_;
        uint64_t cOff = (uint64_t)b * N_ * S_ * ropeSize_ + (uint64_t)n * S_ * ropeSize_ + (uint64_t)s * ropeSize_;
        uint64_t koOff = (uint64_t)b * N_ * S_ * ropeSize_ + (uint64_t)n * S_ * ropeSize_ + (uint64_t)s * ropeSize_;

        // --- Load inputs ---
        AscendC::LocalTensor<dataType> rpIn = ropeInQ_.AllocTensor<dataType>();
        LoadGmToUb(rpIn, kvGM_[rOff], (uint32_t)ropeSize_);
        ropeInQ_.EnQue(rpIn);
        AscendC::LocalTensor<dataType> csIn = ropeCosQ_.AllocTensor<dataType>();
        LoadGmToUb(csIn, cosGM_[cOff], (uint32_t)ropeSize_);
        ropeCosQ_.EnQue(csIn);
        AscendC::LocalTensor<dataType> snIn = ropeSinQ_.AllocTensor<dataType>();
        LoadGmToUb(snIn, sinGM_[cOff], (uint32_t)ropeSize_);
        ropeSinQ_.EnQue(snIn);
        AscendC::LocalTensor<dataType> rpOut = ropeOutQ_.AllocTensor<dataType>();

        rpIn = ropeInQ_.DeQue<dataType>();
        csIn = ropeCosQ_.DeQue<dataType>();
        snIn = ropeSinQ_.DeQue<dataType>();

        AscendC::LocalTensor<float> rpFp32, csFp32, snFp32, outFp32;
        PrepareInputHelper<dataType>(rpFp32, rpIn, ropeCastBuf_, ropeSize_);
        PrepareInputHelper<dataType>(csFp32, csIn, ropeCosCastBuf_, ropeSize_);
        PrepareInputHelper<dataType>(snFp32, snIn, ropeSinCastBuf_, ropeSize_);
        if constexpr (std::is_same_v<dataType, float>) {
            outFp32 = rpOut.template ReinterpretCast<float>();
        } else {
            outFp32 = ropeOutCastBuf_.Get<float>();
        }

        AscendC::LocalTensor<float> workBuf = ropeFp32Buf_.Get<float>();
        // workBuf layout: [0..half-1] = evens, [half..2*half-1] = odds
        //   [2*half..3*half-1] = cos_even/odd, [3*half..4*half-1] = sin_even/odd
        // Since ropeFp32Buf_ = 64*float = 256 bytes but we need 4*32=128 more...
        // ropeFp32Buf_ size = 64*(128?) →
        // Actually ropeFp32Buf_ is ROPE_SIZE_ALIGN * sizeof(float) = 64*4 = 256 bytes.
        // We need 2*half=64 for evens+odds, 2*half=64 for cos+sin = 128 bytes total, plus temp.
        // Each half = 32 floats = 128 bytes. We need:
        //   rope_even (32), rope_odd (32), cos_even (32), sin_even (32) = 128 = 512 bytes.

        // Use Mul on adjacent pairs directly — no interleave needed for the computation!
        // RoPE formula in standard order:
        //   out[2i]   = rope[2i] * cos[2i] - rope[2i+1] * sin[2i]
        //   out[2i+1] = rope[2i+1] * cos[2i+1] + rope[2i] * sin[2i+1]
        // Since cos[2i]==cos[2i+1] and sin[2i]==sin[2i+1] for real RoPE,
        // but for random test cos/sin they may differ.
        // We handle both cases by computing the formula correctly.

        // Approach: convert to interleaved order directly in the output.
        // For standard→interleaved: even positions go to [0..half-1], odd to [half..ropeSize-1]

        // Step 1: split rope into evens/odds using Mul with identity mask pattern
        // Use a stride-2 approach with Mul and Add vectors

        // Simpler approach: do pair-wise computation using Mul on subsets
        // half elements each
        // rope_even[i] = ropeFp32[2*i], rope_odd[i] = ropeFp32[2*i+1]
        //
        // For extraction: use two-pass vector multiplication
        // Build a common interleaved result directly

        // Step A: Extract evens and odds via GatherMask
        // GatherMask with pattern "P0101" gives evens from 64-element source
        // GatherMask with pattern "P1010" gives odds
        // Each produces 32 elements

        // rope_even = GatherMask(rpFp32, "P0101")  → 32 elements
        // rope_odd  = GatherMask(rpFp32, "P1010")  → 32 elements

        // Step B: Same for cos and sin → cos_even, cos_odd, sin_even, sin_odd
        // Step C: first_half = rope_even * cos_even - rope_odd * sin_even
        // Step D: second_half = rope_odd * cos_odd + rope_even * sin_odd
        // Step E: Write to outFp32 as [first_half | second_half]

        // Since we have only ropeFp32Buf_ (256 bytes), we process incrementally
        // We'll do it step by step, reusing buffers

        // Use ropeFp32Buf_ for temporary even/odd extraction
        // First 32 floats [0..31]: rope_even or temp data
        // Next 32 floats [32..63]: rope_odd or temp data

        // Actually, let me just compute directly with pairs, no interleave needed.
        // The key insight: we can treat the 64-element vector as 32 pairs,
        // and use Mul with different subsets to compute each pair.

        // But AscendC Mul works on contiguous segments, not pairs.
        // Let me use this approach:
        // 1. evens = GatherMask(rope_in, "P0101") on ropeFp32
        // 2. odds = GatherMask(rope_in, "P1010")
        // 3. cos_even, cos_odd, sin_even, sin_odd similarly
        // 4. first_half = evens*cos_even - odds*sin_even
        // 5. second_half = odds*cos_odd + evens*sin_odd
        // 6. Output = [first_half | second_half]

        // Allocate offsets in ropeFp32Buf_ (64 floats = 256 bytes total)
        // We need: evens(32), odds(32), tmp(32), tmp2(32) = 128 floats = 512 bytes
        // ropeFp32Buf_ only has 64 floats. So we reuse and compute step by step.

        // Let me use a different strategy: use GatherMask sequentially
        // 1. GatherMask evens → workBuf[0..31]
        // 2. GatherMask odds → workBuf[0..31] (overwrite evens)
        // 3. GatherMask cos_even → workBuf[32..63]
        // But then we need odds for the computation...

        // REVISED APPROACH: Use three dedicated TBufs for even/odd/tmp
        // Reuse rmsReduceBuf_ (TILE_RMS * 4 = 1024 bytes) as scratch
        // That gives us plenty of room!

        const int32_t H = half; // 32
        // Use rmsReduceBuf_ as scratch space: float access
        AscendC::LocalTensor<float> sc = rmsReduceBuf_.Get<float>();
        // sc layout: [0..H-1]=rope_even, [H..2H-1]=rope_odd,
        //            [2H..3H-1]=cos_even, [3H..4H-1]=cos_odd,
        //            [4H..5H-1]=sin_even, [5H..6H-1]=sin_odd
        // Total = 6*32 = 192 floats, fits in 1024 bytes = 256 floats ✓

        // Extract evens and odds from rope_in (64 elems) using GatherMask
        {
            AscendC::GatherMask(sc, rpFp32, AscendC::GatherMaskMode::P0101, 0, 0);      // rope_even[0..H-1]
            AscendC::GatherMask(sc[H], rpFp32, AscendC::GatherMaskMode::P1010, 0, 0);     // rope_odd[H..2H-1]
            AscendC::GatherMask(sc[2*H], csFp32, AscendC::GatherMaskMode::P0101, 0, 0);   // cos_even[2H..3H-1]
            AscendC::GatherMask(sc[3*H], csFp32, AscendC::GatherMaskMode::P1010, 0, 0);   // cos_odd[3H..4H-1]
            AscendC::GatherMask(sc[4*H], snFp32, AscendC::GatherMaskMode::P0101, 0, 0);   // sin_even[4H..5H-1]
            AscendC::GatherMask(sc[5*H], snFp32, AscendC::GatherMaskMode::P1010, 0, 0);   // sin_odd[5H..6H-1]
        }

        // Compute first_half = rope_even * cos_even - rope_odd * sin_even
        // Compute second_half = rope_odd * cos_odd + rope_even * sin_odd
        // Reuse workBuf[0..31] for first_half, workBuf[32..63] for second_half
        AscendC::LocalTensor<float> fh = workBuf;         // first_half[0..H-1]
        AscendC::LocalTensor<float> sh = workBuf[H];      // second_half[H..2H-1]

        AscendC::Mul(fh, sc, sc[2*H], H);                 // fh = rope_even * cos_even
        AscendC::Mul(sh, sc[H], sc[4*H], H);              // temp = rope_odd * sin_even
        AscendC::Sub(fh, fh, sh, H);                      // fh = first_half

        AscendC::Mul(sh, sc[H], sc[3*H], H);              // sh = rope_odd * cos_odd
        // Use sc[H] as temp for rope_even * sin_odd
        AscendC::Mul(sc[H], sc, sc[5*H], H);              // sc[H] = rope_even * sin_odd
        AscendC::Add(sh, sh, sc[H], H);                   // sh = second_half

        // Write output in interleaved order: [first_half | second_half]
        // outFp32[0..H-1] = fh, outFp32[H..2H-1] = sh
        AscendC::DataCopy(outFp32, fh, H);                // copy first_half
        AscendC::DataCopy(outFp32[H], sh, H);             // copy second_half

        FinalizeOutputHelper<dataType>(rpOut, outFp32, ropeSize_);

        ropeInQ_.FreeTensor(rpIn);
        ropeCosQ_.FreeTensor(csIn);
        ropeSinQ_.FreeTensor(snIn);
        ropeOutQ_.EnQue(rpOut);

        rpOut = ropeOutQ_.DeQue<dataType>();
        StoreUbToGm(kEmbedOutGM_[koOff], rpOut, (uint32_t)ropeSize_);
        ropeOutQ_.FreeTensor(rpOut);
    }

    // =======================================================================
    // Cache scatter (Norm mode)
    // =======================================================================
    __aicore__ inline void CacheScatter(int32_t b, int32_t n, int32_t s)
    {
        // Read index[b, s] (1 int64_t)
        AscendC::LocalTensor<int64_t> idxL = idxBuf_.Get<int64_t>();
        AscendC::DataCopyExtParams icp{1, sizeof(int64_t), 0, 0, 0};
        AscendC::DataCopyPadExtParams<int64_t> ipp{true, 0, 0, (int64_t)0};
        AscendC::DataCopyPad(idxL, indexGM_[(uint64_t)b * S_ + s], icp, ipp);
        AscendC::PipeBarrier<PIPE_MTE2>();
        int64_t idx = idxL.GetValue(0);
        if (idx < 0 || idx >= kCacheSeq_) return;

        // Scatter k_embed to k_cache_out[b, n, idx, :]
        uint64_t kOff = (uint64_t)b * N_ * S_ * ropeSize_ + (uint64_t)n * S_ * ropeSize_ + (uint64_t)s * ropeSize_;
        uint64_t kcOff = (uint64_t)b * N_ * kCacheSeq_ * ropeSize_ + (uint64_t)n * kCacheSeq_ * ropeSize_ + (uint64_t)idx * ropeSize_;

        AscendC::LocalTensor<dataType> kIn = cacheInQ_.AllocTensor<dataType>();
        LoadGmToUb(kIn, kEmbedOutGM_[kOff], (uint32_t)ropeSize_);
        cacheInQ_.EnQue(kIn);
        AscendC::LocalTensor<dataType> kOut = cacheOutQ_.AllocTensor<dataType>();
        kIn = cacheInQ_.DeQue<dataType>();
        // Copy directly
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(kOut, kIn, ropeSize_);
        } else {
            AscendC::Cast(kOut, kIn, AscendC::RoundMode::CAST_NONE, ropeSize_);
        }
        cacheInQ_.FreeTensor(kIn);
        cacheOutQ_.EnQue(kOut);
        kOut = cacheOutQ_.DeQue<dataType>();
        StoreUbToGm(kCacheOutGM_[kcOff], kOut, (uint32_t)ropeSize_);
        cacheOutQ_.FreeTensor(kOut);

        // Scatter v to ckv_cache_out[b, n, idx, :]
        uint64_t vOff = (uint64_t)b * N_ * S_ * rmsSize_ + (uint64_t)n * S_ * rmsSize_ + (uint64_t)s * rmsSize_;
        uint64_t ccOff = (uint64_t)b * N_ * ckvCacheSeq_ * rmsSize_ + (uint64_t)n * ckvCacheSeq_ * rmsSize_ + (uint64_t)idx * rmsSize_;

        int32_t nTiles = CeilDivU32((uint32_t)rmsSize_, TILE_RMS);
        for (int32_t t = 0; t < nTiles; ++t) {
            int32_t cs = t * TILE_RMS;
            int32_t len = (cs + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - cs);

            AscendC::LocalTensor<dataType> vIn = cacheInQ_.AllocTensor<dataType>();
            LoadGmToUb(vIn, vOutGM_[vOff + cs], (uint32_t)len);
            cacheInQ_.EnQue(vIn);
            AscendC::LocalTensor<dataType> vOut = cacheOutQ_.AllocTensor<dataType>();
            vIn = cacheInQ_.DeQue<dataType>();
            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::DataCopy(vOut, vIn, len);
            } else {
                AscendC::Cast(vOut, vIn, AscendC::RoundMode::CAST_NONE, len);
            }
            cacheInQ_.FreeTensor(vIn);
            cacheOutQ_.EnQue(vOut);
            vOut = cacheOutQ_.DeQue<dataType>();
            StoreUbToGm(ckvCacheOutGM_[ccOff + cs], vOut, (uint32_t)len);
            cacheOutQ_.FreeTensor(vOut);
        }
    }

private:
    int32_t B_=0, N_=0, S_=0, D_=0;
