// Minimal diagnostic kernel: identity pass-through for cache outputs
// BNSD layout. dtype dispatch: fp16/bf16.

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_SIZE = 256;

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * (uint32_t)sizeof(T), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * (uint32_t)sizeof(T), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) return 0U;
    return (a + b - 1U) / b;
}

template <typename dataType>
class KvRmsnormRopeCacheNormKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin,
        GM_ADDR index, GM_ADDR k_cache, GM_ADDR ckv_cache,
        GM_ADDR kco, GM_ADDR cco, GM_ADDR keo, GM_ADDR vo,
        int32_t B, int32_t N, int32_t S, int32_t D,
        int32_t rs, int32_t ros, int32_t kcs, int32_t ccs,
        int32_t ucn, int32_t tpc, float eps)
    {
        B_ = B; N_ = N; S_ = S; D_ = D;
        rmsSize_ = rs; ropeSize_ = ros;
        kCacheSeq_ = kcs; ckvCacheSeq_ = ccs;
        usedCoreNum_ = ucn; tasksPerCore_ = tpc;

        uint64_t kvSz  = (uint64_t)B * N * S * D;
        uint64_t cosSz = (uint64_t)B * N * S * ros;
        uint64_t kcSz  = (uint64_t)B * N * kcs * ros;
        uint64_t ccSz  = (uint64_t)B * N * ccs * rs;
        uint64_t keSz  = (uint64_t)B * N * S * ros;
        uint64_t voSz  = (uint64_t)B * N * S * rs;

        kCacheOutGM_.SetGlobalBuffer((__gm__ dataType*)kco, kcSz);
        ckvCacheOutGM_.SetGlobalBuffer((__gm__ dataType*)cco, ccSz);
        kEmbedOutGM_.SetGlobalBuffer((__gm__ dataType*)keo, keSz);
        vOutGM_.SetGlobalBuffer((__gm__ dataType*)vo, voSz);

        // Also load from k_cache and ckv_cache
        if ASCEND_IS_AIV {
            pipe_.InitBuffer(copyQ_, BUFFER_NUM, TILE_SIZE * sizeof(dataType));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int32_t totalHeads = B_ * N_;
            for (int32_t li = 0; li < tasksPerCore_; ++li) {
                int32_t hg = coreIdx * tasksPerCore_ + li;
                if (hg >= totalHeads) continue;
                int32_t b = hg / N_;
                int32_t n = hg % N_;

                // For each seq position: copy k_cache slice to k_cache_out
                // This is an identity pass-through — no RMSNorm or RoPE
                // Just verifies the kernel infrastructure works
                {
                    uint64_t kcSzTotal = (uint64_t)kCacheSeq_ * ropeSize_;
                    uint32_t nTiles = CeilDivU32((uint32_t)kcSzTotal, TILE_SIZE);
                    for (uint32_t t = 0; t < nTiles; ++t) {
                        uint32_t cs = t * TILE_SIZE;
                        uint32_t len = (cs + TILE_SIZE <= kcSzTotal) ? TILE_SIZE : (kcSzTotal - cs);
                        uint64_t off = (uint64_t)b * N_ * kCacheSeq_ * ropeSize_
                                     + (uint64_t)n * kCacheSeq_ * ropeSize_
                                     + cs;
                        // Load from k_cache copy area
                        AscendC::LocalTensor<dataType> tmp = copyQ_.AllocTensor<dataType>();
                        AscendC::DataCopyExtParams cp{1, len * (uint32_t)sizeof(dataType), 0, 0, 0};
                        AscendC::DataCopyPadExtParams<dataType> pp{true, 0, 0, (dataType)0};
                        AscendC::DataCopyPad(tmp, (AscendC::GlobalTensor<dataType>)tmp.GetOrigin(), cp, pp);
                        copyQ_.EnQue(tmp);
                        tmp = copyQ_.DeQue<dataType>();
                        AscendC::DataCopyExtParams wcp{1, len * (uint32_t)sizeof(dataType), 0, 0, 0};
                        AscendC::DataCopyPad(kCacheOutGM_[off], tmp, wcp);
                        copyQ_.FreeTensor(tmp);
                    }
                }
            }
        }
    }

private:
    int32_t B_=0, N_=0, S_=0, D_=0;
    int32_t rmsSize_=0, ropeSize_=0;
    int32_t kCacheSeq_=0, ckvCacheSeq_=0;
    int32_t usedCoreNum_=0, tasksPerCore_=0;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<dataType> kCacheOutGM_, ckvCacheOutGM_;
    AscendC::GlobalTensor<dataType> kEmbedOutGM_, vOutGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> copyQ_;
};

template <typename... XA>
__aicore__ inline void DispatchKRC(
    GM_ADDR kv, GM_ADDR g, GM_ADDR c, GM_ADDR s, GM_ADDR idx,
    GM_ADDR kc, GM_ADDR cc, GM_ADDR kco, GM_ADDR cco, GM_ADDR keo, GM_ADDR vo,
    int32_t B, int32_t N, int32_t S, int32_t D,
    int32_t rs, int32_t ros, int32_t kcs, int32_t ccs,
    int32_t ucn, int32_t tpc, float eps, int64_t dFlag, XA... xa)
{
    if (dFlag == 1) {
        KvRmsnormRopeCacheNormKernel<half> k;
        k.Init(kv,g,c,s,idx,kc,cc,kco,cco,keo,vo,B,N,S,D,rs,ros,kcs,ccs,ucn,tpc,eps);
        k.Process();
    } else {
        KvRmsnormRopeCacheNormKernel<bfloat16_t> k;
        k.Init(kv,g,c,s,idx,kc,cc,kco,cco,keo,vo,B,N,S,D,rs,ros,kcs,ccs,ucn,tpc,eps);
        k.Process();
    }
}

extern "C" __global__ __aicore__ void kv_rmsnorm_rope_cache_norm(
    GM_ADDR kv, GM_ADDR g, GM_ADDR c, GM_ADDR s, GM_ADDR idx,
    GM_ADDR kc, GM_ADDR cc, GM_ADDR kco, GM_ADDR cco, GM_ADDR keo, GM_ADDR vo,
    int32_t B, int32_t N, int32_t S, int32_t D,
    int32_t rs, int32_t ros, int32_t kcs, int32_t ccs,
    int32_t ucn, int32_t tpc, float eps, int64_t dFlag)
{
    DispatchKRC(kv,g,c,s,idx,kc,cc,kco,cco,keo,vo,B,N,S,D,rs,ros,kcs,ccs,ucn,tpc,eps,dFlag);
}
