// AscendC KV RMSNorm + RoPE + Cache kernel — Norm cache mode
// BNSD layout, dtype dispatch fp16/bf16 via dtypeFlag

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t TILE_RMS = 256;
constexpr int32_t ROPE_SIZE = 64;

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) return 0U;
    return (a + b - 1U) / b;
}

__aicore__ inline uint32_t AlignUp32(uint32_t x)
{
    return ((x + 31U) / 32U) * 32U;
}

template <typename T>
__aicore__ inline void LoadGm(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * (uint32_t)sizeof(T), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreGm(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * (uint32_t)sizeof(T), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

template <typename T>
__aicore__ inline AscendC::RoundMode RMode()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) return AscendC::RoundMode::CAST_ROUND;
    return AscendC::RoundMode::CAST_NONE;
}

// FP16/BF16 → FP32 cast into output buffer (dst set to castBuf or reinterpret)
template <typename T>
__aicore__ inline void ToFp32(
    AscendC::LocalTensor<float> &dst, AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf, int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// FP32 → FP16/BF16 cast into output tensor
template <typename T>
__aicore__ inline void FromFp32(
    AscendC::LocalTensor<T> &out, AscendC::LocalTensor<float> &src, int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, RMode<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// Kernel Class
// =========================================================================
template <typename T>
class KvRmsnormRopeCacheKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin,
        GM_ADDR index, GM_ADDR k_cache, GM_ADDR ckv_cache,
        GM_ADDR kco, GM_ADDR cco, GM_ADDR keo, GM_ADDR vo,
        int32_t B, int32_t N, int32_t S, int32_t D,
        int32_t rs, int32_t ros, int32_t kcs, int32_t ccs,
        int32_t ucn, int32_t tpc, float eps)
    {
        B_ = B; N_ = N; S_ = S; D_ = D;
        rmsSize_ = rs; ropeSize_ = ros;
        kCacheSeq_ = kcs; ckvCacheSeq_ = ccs;
        usedCoreNum_ = ucn; tasksPerCore_ = tpc;
        eps_ = eps;

        uint64_t qN = (uint64_t)N;
        kvGM_.SetGlobalBuffer((__gm__ T*)kv, (uint64_t)B * qN * S * D);
        gammaGM_.SetGlobalBuffer((__gm__ T*)gamma, rs);
        cosGM_.SetGlobalBuffer((__gm__ T*)cos, (uint64_t)B * qN * S * ros);
        sinGM_.SetGlobalBuffer((__gm__ T*)sin, (uint64_t)B * qN * S * ros);
        idxGM_.SetGlobalBuffer((__gm__ int64_t*)index, (uint64_t)B * S);
        kCacheOutGM_.SetGlobalBuffer((__gm__ T*)kco, (uint64_t)B * qN * kcs * ros);
        ckvCacheOutGM_.SetGlobalBuffer((__gm__ T*)cco, (uint64_t)B * qN * ccs * rs);
        kEmbOutGM_.SetGlobalBuffer((__gm__ T*)keo, (uint64_t)B * qN * S * ros);
        vOutGM_.SetGlobalBuffer((__gm__ T*)vo, (uint64_t)B * qN * S * rs);

        if ASCEND_IS_AIV { InitBufs(); }
    }

    __aicore__ inline void InitBufs()
    {
        // RMS queues
        pipe_.InitBuffer(rmsInQ_, BUFFER_NUM, TILE_RMS * sizeof(T));
        pipe_.InitBuffer(rmsGamQ_, BUFFER_NUM, TILE_RMS * sizeof(T));
        pipe_.InitBuffer(rmsOutQ_, BUFFER_NUM, TILE_RMS * sizeof(T));
        // RoPE queues
        pipe_.InitBuffer(ropeInQ_, BUFFER_NUM, ROPE_SIZE * sizeof(T));
        pipe_.InitBuffer(ropeCosQ_, BUFFER_NUM, ROPE_SIZE * sizeof(T));
        pipe_.InitBuffer(ropeSinQ_, BUFFER_NUM, ROPE_SIZE * sizeof(T));
        pipe_.InitBuffer(ropeOutQ_, BUFFER_NUM, ROPE_SIZE * sizeof(T));
        // Cache queues
        pipe_.InitBuffer(cacheQ_, BUFFER_NUM, TILE_RMS * sizeof(T));
        // Compute buffers
        pipe_.InitBuffer(sqBuf_, TILE_RMS * sizeof(float));
        pipe_.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe_.InitBuffer(invBuf_, sizeof(float));
        pipe_.InitBuffer(rpBuf_, ROPE_SIZE * sizeof(float));
        // Cast buffers (only for fp16/bf16)
        if constexpr (!std::is_same_v<T, float>) {
            pipe_.InitBuffer(rmsCBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(rmsGCBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(rmsOCBuf_, TILE_RMS * sizeof(float));
            pipe_.InitBuffer(ropeCBuf_, ROPE_SIZE * sizeof(float));
            pipe_.InitBuffer(ropeCCBuf_, ROPE_SIZE * sizeof(float));
            pipe_.InitBuffer(ropeSCBuf_, ROPE_SIZE * sizeof(float));
            pipe_.InitBuffer(ropeOCBuf_, ROPE_SIZE * sizeof(float));
            pipe_.InitBuffer(cacheCBuf_, TILE_RMS * sizeof(float));
        }
        // Index buffer (32B aligned)
        pipe_.InitBuffer(idxBuf_, 4 * sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t cid = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            int32_t total = B_ * N_;
            for (int32_t li = 0; li < tasksPerCore_; ++li) {
                int32_t hg = cid * tasksPerCore_ + li;
                if (hg >= total) continue;
                int32_t b = hg / N_;
                int32_t n = hg % N_;

                for (int32_t s = 0; s < S_; ++s) {
                    float invRms = InvRms(b, n, s);
                    RmsNormOut(b, n, s, invRms);
                    RopeOut(b, n, s);
                    if (kCacheSeq_ > 0) {
                        AscendC::PipeBarrier<PIPE_MTE2>();
                        AscendC::PipeBarrier<PIPE_ALL>();
                        CacheWr(b, n, s);
                    }
                }
            }
        }
    }

private:
    // =============== RMSNorm: compute invRms ===============
    __aicore__ inline float InvRms(int32_t b, int32_t n, int32_t s)
    {
        float sumSq = 0.0f;
        int32_t nt = CeilDivU32((uint32_t)rmsSize_, TILE_RMS);
        for (int32_t t = 0; t < nt; ++t) {
            int32_t cs = t * TILE_RMS;
            int32_t len = (cs + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - cs);
            uint64_t off = (uint64_t)b * N_ * S_ * D_ + (uint64_t)n * S_ * D_ + (uint64_t)s * D_ + cs;

            AscendC::LocalTensor<T> in = rmsInQ_.AllocTensor<T>();
            LoadGm(in, kvGM_[off], (uint32_t)len);
            rmsInQ_.EnQue(in);
            in = rmsInQ_.DeQue<T>();

            AscendC::LocalTensor<float> fx;
            ToFp32<T>(fx, in, rmsCBuf_, len);
            AscendC::LocalTensor<float> sq = sqBuf_.Get<float>();
            AscendC::LocalTensor<float> sm = sumBuf_.Get<float>();
            AscendC::Mul(sq, fx, fx, len);
            AscendC::ReduceSum<float>(sm, sq, sq, len);
            sumSq += sm.GetValue(0);
            rmsInQ_.FreeTensor(in);
        }
        float ms = sumSq / (float)rmsSize_ + eps_;
        AscendC::LocalTensor<float> st = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> iv = invBuf_.Get<float>();
        AscendC::Duplicate(st, ms, 1);
        AscendC::Rsqrt(iv, st, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        float r = iv.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();
        return r;
    }

    // =============== RMSNorm: normalize + gamma → v_out ===============
    __aicore__ inline void RmsNormOut(int32_t b, int32_t n, int32_t s, float invRms)
    {
        int32_t nt = CeilDivU32((uint32_t)rmsSize_, TILE_RMS);
        for (int32_t t = 0; t < nt; ++t) {
            int32_t cs = t * TILE_RMS;
            int32_t len = (cs + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - cs);
            uint64_t off = (uint64_t)b * N_ * S_ * D_ + (uint64_t)n * S_ * D_ + (uint64_t)s * D_ + cs;
            uint64_t vOff = (uint64_t)b * N_ * S_ * rmsSize_ + (uint64_t)n * S_ * rmsSize_ + (uint64_t)s * rmsSize_ + cs;

            AscendC::LocalTensor<T> xin = rmsInQ_.AllocTensor<T>();
            LoadGm(xin, kvGM_[off], (uint32_t)len);
            rmsInQ_.EnQue(xin);
            AscendC::LocalTensor<T> gin = rmsGamQ_.AllocTensor<T>();
            LoadGm(gin, gammaGM_[cs], (uint32_t)len);
            rmsGamQ_.EnQue(gin);
            AscendC::LocalTensor<T> yout = rmsOutQ_.AllocTensor<T>();

            xin = rmsInQ_.DeQue<T>();
            gin = rmsGamQ_.DeQue<T>();

            AscendC::LocalTensor<float> xf, gf, yf;
            ToFp32<T>(xf, xin, rmsCBuf_, len);
            ToFp32<T>(gf, gin, rmsGCBuf_, len);
            if constexpr (std::is_same_v<T, float>) {
                yf = yout.template ReinterpretCast<float>();
            } else {
                yf = rmsOCBuf_.Get<float>();
            }

            AscendC::Muls(yf, xf, invRms, len);
            AscendC::Mul(yf, yf, gf, len);
            FromFp32<T>(yout, yf, len);

            rmsInQ_.FreeTensor(xin);
            rmsGamQ_.FreeTensor(gin);
            rmsOutQ_.EnQue(yout);

            yout = rmsOutQ_.DeQue<T>();
            StoreGm(vOutGM_[vOff], yout, (uint32_t)len);
            rmsOutQ_.FreeTensor(yout);
        }
    }

    // =============== RoPE computation ===============
    __aicore__ inline void RopeOut(int32_t b, int32_t n, int32_t s)
    {
        if (ropeSize_ == 0) return;
        int32_t H = ropeSize_ / 2;
        uint64_t rOff = (uint64_t)b * N_ * S_ * D_ + (uint64_t)n * S_ * D_ + (uint64_t)s * D_ + rmsSize_;
        uint64_t cOff = (uint64_t)b * N_ * S_ * ropeSize_ + (uint64_t)n * S_ * ropeSize_ + (uint64_t)s * ropeSize_;
        uint64_t koOff = (uint64_t)b * N_ * S_ * ropeSize_ + (uint64_t)n * S_ * ropeSize_ + (uint64_t)s * ropeSize_;

        // Load rope_in, cos, sin
        AscendC::LocalTensor<T> rIn = ropeInQ_.AllocTensor<T>();
        LoadGm(rIn, kvGM_[rOff], (uint32_t)ropeSize_);
        ropeInQ_.EnQue(rIn);
        AscendC::LocalTensor<T> cIn = ropeCosQ_.AllocTensor<T>();
        LoadGm(cIn, cosGM_[cOff], (uint32_t)ropeSize_);
        ropeCosQ_.EnQue(cIn);
        AscendC::LocalTensor<T> sIn = ropeSinQ_.AllocTensor<T>();
        LoadGm(sIn, sinGM_[cOff], (uint32_t)ropeSize_);
        ropeSinQ_.EnQue(sIn);
        AscendC::LocalTensor<T> rOut = ropeOutQ_.AllocTensor<T>();

        rIn = ropeInQ_.DeQue<T>();
        cIn = ropeCosQ_.DeQue<T>();
        sIn = ropeSinQ_.DeQue<T>();

        AscendC::LocalTensor<float> rf, cf, sf, of;
        ToFp32<T>(rf, rIn, ropeCBuf_, ropeSize_);
        ToFp32<T>(cf, cIn, ropeCCBuf_, ropeSize_);
        ToFp32<T>(sf, sIn, ropeSCBuf_, ropeSize_);
        if constexpr (std::is_same_v<T, float>) {
            of = rOut.template ReinterpretCast<float>();
        } else {
            of = ropeOCBuf_.Get<float>();
        }

        // Scratch buffer for RoPE computation
        AscendC::LocalTensor<float> sc = rpBuf_.Get<float>();
        // sc[0..H-1]=first_half, sc[H..2H-1]=second_half

        // Loop over 32 pairs: fh[i]=rope_even*cos_even - rope_odd*sin_even
        //                    sh[i]=rope_odd*cos_odd + rope_even*sin_odd
        for (int32_t i = 0; i < H; ++i) {
            float a0 = rf.GetValue(2*i);
            float a1 = rf.GetValue(2*i + 1);
            float c0 = cf.GetValue(2*i);
            float c1 = cf.GetValue(2*i + 1);
            float s0 = sf.GetValue(2*i);
            float s1 = sf.GetValue(2*i + 1);

            sc.SetValue(i,     a0 * c0 - a1 * s0);  // first_half[i]
            sc.SetValue(H + i, a1 * c1 + a0 * s1);  // second_half[i]
        }

        // Copy result: first_half (0..H-1), then second_half (H..2H-1)
        for (int32_t i = 0; i < ropeSize_; ++i) {
            of.SetValue(i, sc.GetValue(i));
        }

        FromFp32<T>(rOut, of, ropeSize_);

        ropeInQ_.FreeTensor(rIn);
        ropeCosQ_.FreeTensor(cIn);
        ropeSinQ_.FreeTensor(sIn);
        ropeOutQ_.EnQue(rOut);

        rOut = ropeOutQ_.DeQue<T>();
        StoreGm(kEmbOutGM_[koOff], rOut, (uint32_t)ropeSize_);
        ropeOutQ_.FreeTensor(rOut);
    }

    // =============== Cache scatter (Norm mode) ===============
    __aicore__ inline void CacheWr(int32_t b, int32_t n, int32_t s)
    {
        // Read index[b, s]
        AscendC::LocalTensor<int64_t> il = idxBuf_.Get<int64_t>();
        AscendC::DataCopyExtParams icp{1, sizeof(int64_t), 0, 0, 0};
        AscendC::DataCopyPadExtParams<int64_t> ipp{true, 0, 0, (int64_t)0};
        AscendC::DataCopyPad(il, idxGM_[(uint64_t)b * S_ + s], icp, ipp);
        AscendC::PipeBarrier<PIPE_MTE2>();
        int64_t idx = il.GetValue(0);
        if (idx < 0 || idx >= kCacheSeq_) return;

        // Write k_embed to k_cache_out[b, n, idx, :]
        {
            uint64_t koOff = (uint64_t)b * N_ * S_ * ropeSize_ + (uint64_t)n * S_ * ropeSize_ + (uint64_t)s * ropeSize_;
            uint64_t kcOff = (uint64_t)b * N_ * kCacheSeq_ * ropeSize_ + (uint64_t)n * kCacheSeq_ * ropeSize_ + (uint64_t)idx * ropeSize_;

            AscendC::LocalTensor<T> src = cacheQ_.AllocTensor<T>();
            LoadGm(src, kEmbOutGM_[koOff], (uint32_t)ropeSize_);
            cacheQ_.EnQue(src);
            AscendC::LocalTensor<T> dst = cacheQ_.AllocTensor<T>();
            src = cacheQ_.DeQue<T>();
            // UB-to-UB copy (same type)
            uint32_t bCnt = AlignUp32((uint32_t)ropeSize_);
            AscendC::Duplicate(dst, (T)0, bCnt);
            for (int32_t i = 0; i < ropeSize_; ++i) {
                dst.SetValue(i, src.GetValue(i));
            }
            cacheQ_.FreeTensor(src);
            cacheQ_.EnQue(dst);
            dst = cacheQ_.DeQue<T>();
            StoreGm(kCacheOutGM_[kcOff], dst, (uint32_t)ropeSize_);
            cacheQ_.FreeTensor(dst);
        }

        // Write v to ckv_cache_out[b, n, idx, :]
        {
            int32_t nt = CeilDivU32((uint32_t)rmsSize_, TILE_RMS);
            for (int32_t t = 0; t < nt; ++t) {
                int32_t cs = t * TILE_RMS;
                int32_t len = (cs + TILE_RMS <= rmsSize_) ? TILE_RMS : (rmsSize_ - cs);
                uint64_t voOff = (uint64_t)b * N_ * S_ * rmsSize_ + (uint64_t)n * S_ * rmsSize_ + (uint64_t)s * rmsSize_ + cs;
                uint64_t ccOff = (uint64_t)b * N_ * ckvCacheSeq_ * rmsSize_ + (uint64_t)n * ckvCacheSeq_ * rmsSize_ + (uint64_t)idx * rmsSize_ + cs;

                AscendC::LocalTensor<T> src = cacheQ_.AllocTensor<T>();
                LoadGm(src, vOutGM_[voOff], (uint32_t)len);
                cacheQ_.EnQue(src);
                AscendC::LocalTensor<T> dst = cacheQ_.AllocTensor<T>();
                src = cacheQ_.DeQue<T>();
                uint32_t bCnt = AlignUp32((uint32_t)len);
                AscendC::Duplicate(dst, (T)0, bCnt);
                for (int32_t i = 0; i < len; ++i) {
                    dst.SetValue(i, src.GetValue(i));
                }
                cacheQ_.FreeTensor(src);
                cacheQ_.EnQue(dst);
                dst = cacheQ_.DeQue<T>();
                StoreGm(ckvCacheOutGM_[ccOff], dst, (uint32_t)len);
                cacheQ_.FreeTensor(dst);
            }
        }
    }

private:
    int32_t B_=0, N_=0, S_=0, D_=0;
    int32_t rmsSize_=0, ropeSize_=0, kCacheSeq_=0, ckvCacheSeq_=0;
    int32_t usedCoreNum_=0, tasksPerCore_=0;
    float eps_=0.0f;

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> kvGM_, gammaGM_, cosGM_, sinGM_;
    AscendC::GlobalTensor<int64_t> idxGM_;
    AscendC::GlobalTensor<T> kCacheOutGM_, ckvCacheOutGM_, kEmbOutGM_, vOutGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> rmsInQ_, rmsGamQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> rmsOutQ_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> ropeInQ_, ropeCosQ_, ropeSinQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> ropeOutQ_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cacheQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sqBuf_, sumBuf_, invBuf_, rpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rmsCBuf_, rmsGCBuf_, rmsOCBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> ropeCBuf_, ropeCCBuf_, ropeSCBuf_, ropeOCBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cacheCBuf_, idxBuf_;
};

template <typename... XA>
__aicore__ inline void DispatchKRC(
    GM_ADDR kv, GM_ADDR g, GM_ADDR c, GM_ADDR s, GM_ADDR idx,
    GM_ADDR kc, GM_ADDR cc, GM_ADDR kco, GM_ADDR cco, GM_ADDR keo, GM_ADDR vo,
    int32_t B, int32_t N, int32_t S, int32_t D,
    int32_t rs, int32_t ros, int32_t kcs, int32_t ccs,
    int32_t ucn, int32_t tpc, float eps, int64_t dFlag, XA... xa)
{
    if (dFlag == 1) {
        KvRmsnormRopeCacheKernel<half> k;
        k.Init(kv,g,c,s,idx,kc,cc,kco,cco,keo,vo,B,N,S,D,rs,ros,kcs,ccs,ucn,tpc,eps);
        k.Process();
    } else {
        KvRmsnormRopeCacheKernel<bfloat16_t> k;
        k.Init(kv,g,c,s,idx,kc,cc,kco,cco,keo,vo,B,N,S,D,rs,ros,kcs,ccs,ucn,tpc,eps);
        k.Process();
    }
}

